'use strict';
const lessons = [
 {title:'Meet your first letters',subtitle:'अ, आ, इ · Tiny sounds, big beginnings',icon:'अ',category:'Letters',items:[['अ','a','A short a sound, as in अननस (pineapple)',['A short a sound','A long aa sound','An ee sound']],['आ','aa','A long aa sound, as in आई (mother)',['A long aa sound','A short a sound','An ee sound']],['इ','i','A short i sound, as in इमारत (building)',['A short i sound','An oo sound','A long aa sound']]]},
 {title:'More sounds to discover',subtitle:'ई, उ, ऊ · Listen and say it back',icon:'ई',category:'Letters',items:[['ई','ee','A long ee sound',['A long ee sound','A short u sound','A long aa sound']],['उ','u','A short u sound',['A short u sound','A long ee sound','A long oo sound']],['ऊ','oo','A long oo sound',['A long oo sound','A short i sound','A short a sound']]]},
 {title:'My family & me',subtitle:'Meet the people you love',icon:'म',category:'Words',items:[['आई','aai','Mother',['Mother','Father','Brother']],['बाबा','baabaa','Father',['Father','Sister','Mother']],['मी','mee','I / me',['I / me','You','We']]]},
 {title:'A world of little words',subtitle:'Fruit, water & things around you',icon:'प',category:'Words',items:[['पाणी','paanee','Water',['Water','Milk','Apple']],['आंबा','aambaa','Mango',['Mango','Apple','Banana']],['घर','ghar','House',['House','School','Garden']]]},
 {title:'Let’s say hello',subtitle:'Your first everyday phrases',icon:'न',category:'Phrases',items:[['नमस्कार','namaskaar','Hello',['Hello','Goodbye','Thank you']],['धन्यवाद','dhanyavaad','Thank you',['Thank you','Hello','Yes']],['माझे नाव मित्र आहे.','maajhe naav Mitra aahe','My name is Mitra.',['My name is Mitra.','I want water.','How are you?']]]},
 {title:'Little conversations',subtitle:'Ask, answer & speak with confidence',icon:'ग',category:'Phrases',items:[['तू कसा आहेस?','too kasaa aahes?','How are you? (to a boy)',['How are you? (to a boy)','What is your name?','Where is the house?']],['तू कशी आहेस?','too kashee aahes?','How are you? (to a girl)',['How are you? (to a girl)','Thank you','I want water.']],['मला पाणी हवे आहे.','malaa paanee have aahe','I want water.',['I want water.','My name is Mitra.','I am at home.']]]}
];
const storageKey='marathi-mitra-progress-v1';
let state={results:{},days:[],xp:0};
try{const s=JSON.parse(localStorage.getItem(storageKey));if(s&&typeof s==='object'&&s.results&&typeof s.results==='object'){state={results:s.results,days:Array.isArray(s.days)?s.days:[],xp:Number.isFinite(s.xp)?s.xp:0};}}catch{}
let view='learn',filter='All',session=null,recognizer=null,microphonePractice=null,pronunciationAssessment=null;
const main=document.getElementById('main'),dialog=document.getElementById('lesson-dialog');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function completed(){return lessons.filter((_,i)=>state.results[i]?.passed).length;}
function nextLesson(){return lessons.findIndex((_,i)=>!state.results[i]?.passed);}
function unlocked(i){return i===0||!!state.results[i-1]?.passed;}
function streak(){let d=new Date(),n=0;if(!state.days.includes(dayKey(d)))d.setDate(d.getDate()-1);while(state.days.includes(dayKey(d))){n++;d.setDate(d.getDate()-1);}return n;}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('Progress could not be saved. Please allow browser storage.');}}
let toastTimer;function toast(message){const t=document.getElementById('toast');t.textContent=message;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',5500);}
function level(){const n=completed();return n<2?'Sound explorer':n<4?'Word adventurer':n<6?'Phrase explorer':'Conversation starter';}
function updateHeader(){document.getElementById('xp').textContent=`✦ ${state.xp} XP`;document.getElementById('streak').textContent=`☀ ${streak()} day streak`;document.getElementById('view-name').textContent=({learn:'Learn & play',words:'My word book',rewards:'My rewards',progress:'Parent corner'})[view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function render(){updateHeader();if(view==='learn')renderLearn();if(view==='words')renderWords();if(view==='rewards')renderRewards();if(view==='progress')renderProgress();}
function renderLearn(){const index=nextLesson(),i=index<0?5:index;const today=state.days.includes(dayKey());main.innerHTML=`
 <div class="welcome-line"><div><div class="eyebrow">A LITTLE PRACTICE, A BIG ADVENTURE</div><h1>Ready, little explorer?</h1><p>Let’s discover a little more Marathi today.</p></div><span class="date-pill">${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',weekday:'short'})}</span></div>
 <div class="dashboard"><section><div class="hero-card"><div class="hero-top"><span class="pill">${index<0?'KEEP EXPLORING':`LEVEL ${i+1} · ${lessons[i].category.toUpperCase()}`}</span><span class="time">◷ About 5 minutes</span></div><h2>${index<0?'Look how far you’ve come!':lessons[i].title}</h2><p>${i<2?'Every great conversation starts with a little sound. Listen, play, and say it out loud.':i<4?'Meet useful words for your everyday world. Listen, play, and say them out loud.':'Put your words together. Practise phrases you can use with your family.'}</p><div class="hero-bottom"><button class="primary" data-start="${i}">${index<0?'Play again':'Let’s play'}</button><div class="letter-stack" aria-hidden="true"><span class="letter-tile">अ</span><span class="letter-tile">आ</span><span class="letter-tile">इ</span></div></div></div>
 <div class="section-head"><div><h2>Your learning trail</h2><p>One small step at a time. You’ve got this!</p></div><span class="micro">${completed()} OF 6 COMPLETE</span></div><div class="journey">${lessons.map((l,j)=>`<button class="lesson-row ${state.results[j]?.passed?'complete':j===i?'current':''} ${unlocked(j)?'':'locked'}" data-start="${j}" ${unlocked(j)?'':'disabled'}><span class="lesson-icon">${l.icon}</span><span class="lesson-text"><strong>${j+1}. ${l.title}</strong><small>${l.subtitle}</small></span><span class="lesson-status">${state.results[j]?.passed?'✓ Complete':unlocked(j)?'Play lesson':'⌑ Locked'}</span></button>`).join('')}</div></section>
 <aside class="rail"><div class="rail-card"><h3>Your explorer level</h3><div class="level-top"><span class="level-emblem">✦</span><div><strong>${level()}</strong><small>${completed()===6?'All six levels explored!':`Level ${Math.min(completed()+1,6)} · Keep growing`}</small></div></div><div class="progress-track" role="progressbar" aria-label="Levels complete" aria-valuenow="${completed()}" aria-valuemin="0" aria-valuemax="6"><div style="width:${completed()/6*100}%"></div></div><div class="progress-meta"><span>${completed()} / 6 lessons</span><span>${state.xp} XP earned</span></div></div>
 <div class="rail-card daily-card"><h3>☀ A little every day</h3><p>${today?'You practised today. Lovely work!':'Your mission: finish one little lesson.'}</p><div class="progress-track"><div style="width:${today?100:0}%;background:#d9b659"></div></div><div class="progress-meta"><span>${today?'1':'0'} / 1 lesson today</span><span>5 min goal</span></div><div class="week">${Array.from({length:7},(_,j)=>{let d=new Date();d.setDate(d.getDate()-6+j);return `<div class="day ${state.days.includes(dayKey(d))?'done':''}"><small>${d.toLocaleDateString('en-US',{weekday:'short'}).slice(0,1)}</small><span>${state.days.includes(dayKey(d))?'✓':'·'}</span></div>`;}).join('')}</div></div>
 <div class="rail-card word-card"><span class="eyebrow">A WORD TO TRY TODAY</span><div class="word" lang="mr">नमस्कार</div><p>namaskaar · Hello</p><button data-say="नमस्कार">♫ Hear the word</button></div><p class="tip"><strong>A little grown-up tip</strong><br>Try today’s words together at dinner. A familiar voice makes practice special.</p></aside></div>`;}
function renderWords(){let items=lessons.flatMap((l,i)=>l.items.map((w,item)=>({w,i,item,category:l.category})));const available=items.filter(x=>unlocked(x.i));main.innerHTML=`<div class="page-heading"><div class="eyebrow">LITTLE WORDS, BIG POSSIBILITIES</div><h1>My word book</h1><p>Listen again, then try saying it to someone you love.</p></div><div class="filter-bar">${['All','Letters','Words','Phrases'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="grid-cards">${available.filter(x=>filter==='All'||x.category===filter).map(({w,i,item,category})=>`<div class="vocab-card"><small>${category}</small><div class="dev" lang="mr">${w[0]}</div><p>${w[1]}<br>${w[2]}</p><div class="word-actions"><button class="secondary" data-say="${w[0]}">♫ Listen</button><button class="secondary" data-practice="${i}:${item}">● Say it</button></div></div>`).join('')}</div>${available.filter(x=>filter==='All'||x.category===filter).length?'':'<div class="empty-note">These words are just around the corner. Complete the earlier lessons to unlock them.</div>'}<p class="speak-note">Your word book grows as you unlock lessons. English spellings are sound guides; tap Listen to hear Marathi pronunciation.</p>`;}
const badges=[{name:'First little step',desc:'Complete your first lesson',symbol:'✦',earned:()=>completed()>=1},{name:'Sound explorer',desc:'Complete both letter lessons',symbol:'अ',earned:()=>completed()>=2},{name:'Word collector',desc:'Complete both word lessons',symbol:'▤',earned:()=>completed()>=4},{name:'Conversation starter',desc:'Complete all six lessons',symbol:'☏',earned:()=>completed()>=6},{name:'Three happy days',desc:'Practise three days in a row',symbol:'☀',earned:()=>streak()>=3},{name:'Back for more',desc:'Practise on five different days',symbol:'☆',earned:()=>state.days.length>=5}];
function renderRewards(){main.innerHTML=`<div class="page-heading"><div class="eyebrow">CELEBRATE EVERY SMALL STEP</div><h1>Look what you’re growing!</h1><p>${state.xp} XP earned · ${badges.filter(b=>b.earned()).length} of 6 badges collected</p></div><div class="grid-cards">${badges.map(b=>`<div class="rail-card reward ${b.earned()?'':'unearned'}"><div class="reward-symbol">${b.symbol}</div><h3>${b.name}</h3><p>${b.desc}</p><span class="pill">${b.earned()?'✓ YOU EARNED IT':'KEEP EXPLORING'}</span></div>`).join('')}</div>`;}
function renderProgress(){main.innerHTML=`<div class="page-heading"><div class="eyebrow">A WINDOW INTO THEIR ADVENTURE</div><h1>Little steps, real progress</h1><p>See what your child has practised and what’s coming next.</p></div><div class="progress-summary"><div class="rail-card"><h3>Current stage</h3><div class="number" style="font-size:24px">${level()}</div><small>Lesson ${Math.min(completed()+1,6)} of 6</small></div><div class="rail-card"><h3>Lessons completed</h3><div class="number">${completed()} <small style="font-size:16px">/ 6</small></div><small>${state.xp} total XP</small></div><div class="rail-card"><h3>Days of practice</h3><div class="number">${state.days.length}</div><small>${streak()} day current streak</small></div></div><div class="rail-card"><h2>Learning milestones</h2><table class="progress-table"><thead><tr><th>Lesson</th><th>Quiz accuracy</th><th>Status</th></tr></thead><tbody>${lessons.map((l,i)=>`<tr><td>${l.title}</td><td>${state.results[i]?`${state.results[i].score} / 3`: '—'}</td><td>${state.results[i]?.passed?'Complete':state.results[i]?'Try again':unlocked(i)?'Ready':'Locked'}</td></tr>`).join('')}</tbody></table></div><div class="empty-note" style="margin-top:22px"><strong>Try it together</strong><br>${completed()<2?'Spend five minutes listening to अ, आ, and इ. Take turns copying each sound.':completed()<4?'Ask your child to point to family members and say आई or बाबा. Repeat familiar words during the day.':'Practise a tiny conversation: say नमस्कार, introduce yourself, and ask for water.'}</div><p class="speak-note">A lesson unlocks the next one after at least 2 of 3 quiz answers are correct on the first try and all speaking prompts are practised. This is a practice level, not a language proficiency assessment. Every speaking step needs an estimated pronunciation score of at least 5/10. Progress is saved only in this browser on this device.</p>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;location.hash=view;render();}if(b.dataset.start!==undefined)startLesson(Number(b.dataset.start));if(b.dataset.say)say(b.dataset.say);if(b.dataset.practice){const [i,item]=b.dataset.practice.split(':').map(Number);openSpeakingPractice(i,item);}if(b.dataset.filter){filter=b.dataset.filter;renderWords();}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['learn','words','rewards','progress'].includes(v)){view=v;render();}});
const pronunciationPlayer=document.getElementById('pronunciation-player');
let playbackButton=null,playbackLabel='',playbackRequest=0;
function restorePlaybackButton(){if(playbackButton){playbackButton.textContent=playbackLabel;playbackButton.removeAttribute('aria-busy');playbackButton=null;}}
function stopPronunciation(){playbackRequest++;pronunciationPlayer.pause();restorePlaybackButton();}
async function say(text){
 stopRecognition();microphonePractice?.stop();document.getElementById('my-voice')?.pause();stopPronunciation();
 const file=pronunciationAudio[text];
 if(!file){toast('This pronunciation is not available yet.');return;}
 const request=playbackRequest;
 const button=document.activeElement;
 if(button?.tagName==='BUTTON'){
   playbackButton=button;playbackLabel=button.textContent;
   button.textContent='Loading pronunciation…';button.setAttribute('aria-busy','true');
 }
 pronunciationPlayer.src=new URL(file,document.baseURI).href;
 pronunciationPlayer.playbackRate=1;
 try{await pronunciationPlayer.play();if(request!==playbackRequest)return;
   if(playbackButton){playbackButton.textContent='♫ Playing…';playbackButton.removeAttribute('aria-busy');}
 }catch(error){if(request!==playbackRequest)return;restorePlaybackButton();
   toast(error.name==='NotAllowedError'?'Tap Listen again to allow audio playback.':'Audio could not load. Check your connection and tap Listen again.');
 }
}
pronunciationPlayer.addEventListener('ended',restorePlaybackButton);
pronunciationPlayer.addEventListener('error',restorePlaybackButton);
function disposeMicrophone(){pronunciationAssessment?.dispose();pronunciationAssessment=null;microphonePractice?.dispose();microphonePractice=null;}
function openSpeakingPractice(i,item){if(!Number.isInteger(i)||!Number.isInteger(item)||!lessons[i]?.items[item]||!unlocked(i))return;disposeMicrophone();stopRecognition();session={i,item,phase:'speak',practiceOnly:true,speechScores:{}};document.getElementById('lesson-label').textContent='SPEAKING PRACTICE · '+lessons[i].title;if(!dialog.open)dialog.showModal();renderStep();}
function stopRecognition(){if(recognizer){const active=recognizer;recognizer=null;active.abort();}const button=document.getElementById('speech-check');if(button){button.disabled=false;button.textContent='See the words I say';}}
function startLesson(i){if(!Number.isInteger(i)||!lessons[i]||!unlocked(i))return;stopRecognition();session={i,item:0,phase:'learn',score:0,answered:false,mistake:false,speechScores:{}};document.getElementById('lesson-label').textContent=`LEVEL ${i+1} · ${lessons[i].title}`;if(!dialog.open)dialog.showModal();renderStep();}
function closeLesson(){disposeMicrophone();stopRecognition();stopPronunciation();session=null;dialog.close();}
document.getElementById('close-lesson').onclick=closeLesson;
dialog.addEventListener('cancel',()=>{disposeMicrophone();stopRecognition();session=null;stopPronunciation();});
function renderStep(){if(!session)return;disposeMicrophone();stopRecognition();stopPronunciation();const {i,item,phase}=session;const w=lessons[i].items[item];const content=document.getElementById('lesson-content');document.querySelector('#lesson-progress>div').style.width=`${(item*3+['learn','quiz','speak'].indexOf(phase))/9*100}%`;
 if(phase==='learn'){content.innerHTML=`<div class="eyebrow">${item+1} OF 3 · LISTEN & DISCOVER</div><div class="prompt">Meet a new ${i<2?'sound':'word'}!</div><div class="big-word" lang="mr" style="${w[0].length>9?'font-size:37px':''}">${w[0]}</div><div class="translit">${w[1]}</div><p>${w[2]}</p><button class="listen" id="listen">♫ Hear it slowly</button><p class="speak-note">Listen, look at the letters, and try the sound together.</p><div class="lesson-actions"><button class="primary" id="next">Let’s try a game</button></div>`;document.getElementById('listen').onclick=()=>say(w[0]);document.getElementById('next').onclick=()=>{session.phase='quiz';renderStep();};}
 if(phase==='quiz'){const choices=w[3].map((a,j)=>({a,j})).sort(()=>Math.random()-.5);content.innerHTML=`<div class="eyebrow">${item+1} OF 3 · LITTLE WORD GAME</div><div class="prompt">${i<2?'Which sound is this?':'What does this mean?'}</div><div class="big-word" lang="mr" style="${w[0].length>9?'font-size:37px':''}">${w[0]}</div><button class="listen" id="listen">♫ Listen again</button><div class="options">${choices.map(c=>`<button class="option" data-answer="${c.j}">${c.a}</button>`).join('')}</div><div class="feedback" id="feedback" role="status"></div><div class="lesson-actions"><button class="primary" id="next" hidden>Time to say it</button></div>`;document.getElementById('listen').onclick=()=>say(w[0]);content.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(session.answered)return;if(Number(b.dataset.answer)===0){if(!session.mistake)session.score++;session.answered=true;b.classList.add('correct');content.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);document.getElementById('feedback').textContent='Lovely work! Let’s say it out loud.';document.getElementById('next').hidden=false;}else{session.mistake=true;b.classList.add('wrong');b.disabled=true;document.getElementById('feedback').textContent='Good try. Listen once more and choose another answer.';}});document.getElementById('next').onclick=()=>{session.phase='speak';renderStep();};}
 if(phase==='speak'){
   content.innerHTML=`<div class="eyebrow">${item+1} OF 3 · YOUR TURN TO SPEAK</div><div class="prompt">Say it out loud!</div><div class="big-word" lang="mr" style="${w[0].length>9?'font-size:37px':''}">${w[0]}</div><div class="translit">${w[1]}</div><p>${w[2]}</p><button class="listen" id="listen">♫ Listen first</button><div class="microphone-panel" id="microphone-panel"><span class="mic-symbol" aria-hidden="true">●</span><h3>Your turn!</h3><p class="speak-note">Listen first. Record yourself saying the word.<br>Then play your voice back and try again.</p><button class="primary" id="mic" aria-pressed="false">● Record my voice</button><div class="feedback" id="recording-status" role="status" aria-live="polite">Tap Record my voice to turn on the microphone.</div><audio id="my-voice" controls hidden aria-label="Listen to my voice"></audio></div><div class="score-panel"><button class="primary" id="check-pronunciation" disabled>Check my pronunciation</button><div class="pronunciation-result" id="pronunciation-result" role="status" aria-live="polite"></div></div><p class="speak-note">Checking pronunciation sends this recording to OpenAI for an estimated practice score. This app does not save your audio. Get 5/10 or higher to continue.</p><div class="speech-check-area"><button class="secondary" id="speech-check">See the words I say</button><div class="feedback" id="heard" role="status"></div><p class="speak-note">Optional speech recognition may send audio to your browser’s speech provider.</p></div><div class="lesson-actions"><button class="primary" id="next" disabled>${session.practiceOnly?'Done practising':'Continue'}</button></div>`;
   document.getElementById('listen').onclick=()=>say(w[0]);
   pronunciationAssessment=window.createPronunciationAssessment({button:document.getElementById('check-pronunciation'),result:document.getElementById('pronunciation-result'),continueButton:document.getElementById('next'),target:'word-'+(i*3+item+1),onPass:score=>{if(session)session.speechScores[item]=score;},onReset:()=>{if(session)delete session.speechScores[item];}});
   microphonePractice=window.createMicrophonePractice({button:document.getElementById('mic'),status:document.getElementById('recording-status'),playback:document.getElementById('my-voice'),container:document.getElementById('microphone-panel'),beforeStart:()=>{stopRecognition();stopPronunciation();},onRecordingStarted:()=>pronunciationAssessment?.recordingStarted(),onRecordingReady:blob=>pronunciationAssessment?.recordingReady(blob)});
   const speechButton=document.getElementById('speech-check');
   if(window.SpeechRecognition||window.webkitSpeechRecognition)speechButton.onclick=startSpeechCheck;
   else document.querySelector('.speech-check-area').hidden=true;
   document.getElementById('next').onclick=()=>{if(!pronunciationAssessment?.canContinue()){toast('Practise and get a passing pronunciation score before continuing.');return;}disposeMicrophone();stopRecognition();if(session.practiceOnly){closeLesson();return;}if(session.item===2)finishLesson();else{session.item++;session.phase='learn';session.answered=false;session.mistake=false;renderStep();}};
 }
}
function startSpeechCheck(){
 microphonePractice?.stop();document.getElementById('my-voice')?.pause();stopPronunciation();stopRecognition();
 const API=window.SpeechRecognition||window.webkitSpeechRecognition;
 const heard=document.getElementById('heard'),button=document.getElementById('speech-check');
 if(!API){heard.textContent='Speech recognition is not supported here. Record your voice and listen back instead.';return;}
 try{
   const active=new API();recognizer=active;active.lang='mr-IN';active.interimResults=false;
   button.disabled=true;button.textContent='Listening…';heard.textContent='Say the Marathi word now.';
   active.onresult=e=>{if(recognizer===active)heard.textContent=`I heard: ${e.results[0][0].transcript}`;};
   active.onerror=e=>{if(recognizer!==active)return;heard.textContent=e.error==='not-allowed'?'Speech access was blocked. Allow it in the browser’s site settings or record your voice instead.':'I couldn’t hear that. Try again, or use Record my voice.';};
   active.onend=()=>{if(recognizer!==active)return;button.disabled=false;button.textContent='See the words I say';recognizer=null;};
   active.start();
 }catch{recognizer=null;heard.textContent='Speech recognition could not start. Use Record my voice instead.';button.disabled=false;button.textContent='See the words I say';}
}
function finishLesson(){if(!session||![0,1,2].every(item=>window.isPassingPronunciation(session.speechScores?.[item]))){toast('Each word needs a passing pronunciation score.');return;}const {i,score}=session;const passed=score>=2,previous=state.results[i];let gained=0;if(passed){gained=previous?.passed?10:50;state.xp+=gained;const d=dayKey();if(!state.days.includes(d))state.days.push(d);}if(!previous?.passed||score>previous.score){state.results[i]={score,passed,date:dayKey(),speechScores:{...session.speechScores}};}else{state.results[i].speechScores={...session.speechScores};}save();render();document.querySelector('#lesson-progress>div').style.width='100%';document.getElementById('lesson-content').innerHTML=`<div class="reward-symbol">${passed?'✦':'♡'}</div><div class="prompt">${passed?'You did it, little explorer!':'A little more practice'}</div><p>You answered ${score} of 3 correctly on the first try<br>and practised 3 sounds out loud.</p>${passed?`<div class="number">+${gained} XP</div><p>${i===5?'All six levels explored. Keep practising with your family!':'Your next adventure is unlocked.'}</p>`:'<p>Get 2 of 3 correct to unlock the next lesson.<br>Listen again, then give it another go.</p>'}<div class="lesson-actions"><button class="primary" id="done">${passed?'Back to my adventure':'Try again'}</button>${passed?'':'<button class="secondary" id="later">Take a little break</button>'}</div>`;document.getElementById('done').onclick=()=>passed?closeLesson():startLesson(i);if(!passed)document.getElementById('later').onclick=closeLesson;}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_learning_progress',description:'Read device-local Marathi lesson completion and practice progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object.');return {completedLessons:completed(),totalLessons:6,stage:level(),xp:state.xp,practiceDays:state.days.length};}})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'start_marathi_lesson',description:'Open an unlocked Marathi lesson for the learner to practise. Does not complete the lesson.',inputSchema:{type:'object',properties:{lesson:{type:'integer',minimum:1,maximum:6}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='lesson')||!Number.isInteger(input.lesson)||input.lesson<1||input.lesson>6||!unlocked(input.lesson-1))throw new Error('Choose an unlocked lesson from 1 to 6.');startLesson(input.lesson-1);return {lesson:input.lesson,title:lessons[input.lesson-1].title,opened:dialog.open};}})).catch(()=>{});}catch{}}
if(['learn','words','rewards','progress'].includes(location.hash.slice(1)))view=location.hash.slice(1);render();

window.addEventListener('pagehide',()=>{disposeMicrophone();stopRecognition();stopPronunciation();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){microphonePractice?.stop();stopRecognition();stopPronunciation();}});
